INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('83aafac1-6896-5377-8593-bf58f86f8512', 'Greece Greek Law', 'Greek Law 5215/2025', 'Greek Law 5215/2025 establishes regulations for promoting biomethane production, organizing the hydrogen production market, and creating geographically limited hydrogen networks. It aims to enhance environmental protection through sustainability criteria compliance. The law outlines licensing procedures, operational guidelines, and support mechanisms for biomethane and renewable hydrogen production facilities.', 'Greek Law 5215/2025 establishes regulations for promoting biomethane production, organizing the hydrogen production market, and creating geographically limited hydrogen networks. It aims to enhance environmental protection through sustainability criteria compliance. The law outlines licensing procedures, operational guidelines, and support mechanisms for biomethane and renewable hydrogen production facilities.', 'Greek Law 5215/2025 establishes regulations for promoting biomethane production, organizing the hydrogen production market, and creating geographically limited hydrogen networks. It aims to enhance environmental protection through sustainability criteria compliance. The law outlines licensing procedures, operational guidelines, and support mechanisms for biomethane and renewable hydrogen production facilities.', 'Greece', 'climate', 'in_force', '2025-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_28', ARRAY['regulations', 'sdg7', 'mandatory', 'greece', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
