INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f310b114-39c8-5e2e-b979-853a88e1518d', 'Greece Greek Law', 'Greek Law No. 5255/2025', 'Greek Law No. 5255/2025 establishes an Independent Authority for Market Control and Consumer Protection. Its purpose is to create a unified regulatory framework for market oversight, enhancing transparency and consumer protection. The law outlines the authority''s structure, responsibilities, and operational independence, including the governance of its leadership. It applies to all sectors and mandates compliance with its provisions, particularly regarding market practices and consumer rights. The law is mandatory for all businesses operating in Greece.', 'Greek Law No. 5255/2025 establishes an Independent Authority for Market Control and Consumer Protection. Its purpose is to create a unified regulatory framework for market oversight, enhancing transparency and consumer protection. The law outlines the authority''s structure, responsibilities, and operational independence, including the governance of its leadership. It applies to all sectors and mandates compliance with its provisions, particularly regarding market practices and consumer rights. The law is mandatory for all businesses operating in Greece.', 'Greek Law No. 5255/2025 establishes an Independent Authority for Market Control and Consumer Protection. Its purpose is to create a unified regulatory framework for market oversight, enhancing transparency and consumer protection. The law outlines the authority''s structure, responsibilities, and operational independence, including the governance of its leadership. It applies to all sectors and mandates compliance with its provisions, particularly regarding market practices and consumer rights. The law is mandatory for all businesses operating in Greece.', 'Greece', 'governance', 'in_force', '2025-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_31', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'greece']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('084270e5-91a1-58a7-bf1d-035633fddbdb', 'Greece Greek Law', 'Greek Law 5164/2024', 'Greek Law 5164/2024 integrates EU directives on sustainability reporting for companies of varying sizes. It amends regulations and defines obligations for submitting sustainability reports. The law aims to enhance corporate governance and transparency, benefiting businesses, investors, and stakeholders in Greece.', 'Greek Law 5164/2024 integrates EU directives on sustainability reporting for companies of varying sizes. It amends regulations and defines obligations for submitting sustainability reports. The law aims to enhance corporate governance and transparency, benefiting businesses, investors, and stakeholders in Greece.', 'Greek Law 5164/2024 integrates EU directives on sustainability reporting for companies of varying sizes. It amends regulations and defines obligations for submitting sustainability reports. The law aims to enhance corporate governance and transparency, benefiting businesses, investors, and stakeholders in Greece.', 'Greece', 'climate', 'in_force', '2024-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_24', ARRAY['greece', 'sdg16', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6192ca7c-5467-5b25-9fc5-c23320169d46', 'Greece Greek Law', 'Greek Law 5100/2024', 'Greek Law 5100/2024 integrates EU Directive 2022/2523 on global minimum taxation levels for multinational and large-scale domestic groups within the EU. The law outlines rules for calculating and distributing taxes, with a focus on tax transparency and fairness. Targeted at multinational corporations and large domestic entities operating in the European Union.', 'Greek Law 5100/2024 integrates EU Directive 2022/2523 on global minimum taxation levels for multinational and large-scale domestic groups within the EU. The law outlines rules for calculating and distributing taxes, with a focus on tax transparency and fairness. Targeted at multinational corporations and large domestic entities operating in the European Union.', 'Greek Law 5100/2024 integrates EU Directive 2022/2523 on global minimum taxation levels for multinational and large-scale domestic groups within the EU. The law outlines rules for calculating and distributing taxes, with a focus on tax transparency and fairness. Targeted at multinational corporations and large domestic entities operating in the European Union.', 'Greece', 'governance', 'in_force', '2024-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_25', ARRAY['greece', 'sdg16', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('135a96db-9304-51eb-992f-978a3fdfa5cd', 'Greece ESG Reporting Guide', 'ESG Reporting Guide, 2022', 'This Guide is intended to function as a tool with which companies can identify the ESG issues they should consider managing and disclosing, on the basis of their impact on long-term performance. It also offers practical guidelines on the metrics companies should use to disclose this information and communicate it to relevant stakeholders.', 'This Guide is intended to function as a tool with which companies can identify the ESG issues they should consider managing and disclosing, on the basis of their impact on long-term performance. It also offers practical guidelines on the metrics companies should use to disclose this information and communicate it to relevant stakeholders.', 'This Guide is intended to function as a tool with which companies can identify the ESG issues they should consider managing and disclosing, on the basis of their impact on long-term performance. It also offers practical guidelines on the metrics companies should use to disclose this information and communicate it to relevant stakeholders.', 'Greece', 'climate', 'in_force', '2022-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_23', ARRAY['sdg7', 'mandatory', 'mandatory_regulations', 'greece', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('960dd209-3e0e-5c8b-9707-ef8de3ccb09e', 'Greece Greek Law', 'Greek Law 4936/2022', 'Greek Law 4936/2022 aims to transition Greece to climate neutrality by 2050, addressing energy crises and environmental protection. It outlines strategies for emissions reduction, climate adaptation, and financial incentives. The policy targets enhancing resilience, sustainable development, and a smooth transition to a climate-neutral economy, benefiting investors and citizens.', 'Greek Law 4936/2022 aims to transition Greece to climate neutrality by 2050, addressing energy crises and environmental protection. It outlines strategies for emissions reduction, climate adaptation, and financial incentives. The policy targets enhancing resilience, sustainable development, and a smooth transition to a climate-neutral economy, benefiting investors and citizens.', 'Greek Law 4936/2022 aims to transition Greece to climate neutrality by 2050, addressing energy crises and environmental protection. It outlines strategies for emissions reduction, climate adaptation, and financial incentives. The policy targets enhancing resilience, sustainable development, and a smooth transition to a climate-neutral economy, benefiting investors and citizens.', 'Greece', 'climate', 'in_force', '2022-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_30', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'greece']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('80f1e24c-105a-5c98-9c3e-c0cdb0a183c6', 'Greece Hellenic Corporate Governance Code', 'Hellenic Corporate Governance Code', 'This Code constitutes the Hellenic Corporate Governance Code for Companies with securities listed on the stock market, in accordance with Article 17 of Law 4706/2020 and Article 4 of the Decision of the Hellenic Capital Market Commission (Decision 2/905 / 3.3.2021 of the Board of Directors of the Hellenic Capital Market Commission). It replaces the Hellenic Corporate Governance Code for the listed companies issued in 2013 by the HCGC.', 'This Code constitutes the Hellenic Corporate Governance Code for Companies with securities listed on the stock market, in accordance with Article 17 of Law 4706/2020 and Article 4 of the Decision of the Hellenic Capital Market Commission (Decision 2/905 / 3.3.2021 of the Board of Directors of the Hellenic Capital Market Commission). It replaces the Hellenic Corporate Governance Code for the listed companies issued in 2013 by the HCGC.', 'This Code constitutes the Hellenic Corporate Governance Code for Companies with securities listed on the stock market, in accordance with Article 17 of Law 4706/2020 and Article 4 of the Decision of the Hellenic Capital Market Commission (Decision 2/905 / 3.3.2021 of the Board of Directors of the Hellenic Capital Market Commission). It replaces the Hellenic Corporate Governance Code for the listed companies issued in 2013 by the HCGC.', 'Greece', 'governance', 'in_force', '2021-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_22', ARRAY['regulations', 'mandatory', 'sdg16', 'greece', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('88eaacb9-3cff-5668-907c-a1b5329999c2', 'Greece Greek Sustainability Code', 'Greek Sustainability Code 2020', 'The Greek Code of Sustainability is a structured reference system regarding the transparency and self-commitment of Organizations in the issues of Sustainable Development and Responsible Entrepreneurship. It responds to the need to measure the economic, environmental and social performance of Organizations with the aim of strengthening their competitiveness.', 'The Greek Code of Sustainability is a structured reference system regarding the transparency and self-commitment of Organizations in the issues of Sustainable Development and Responsible Entrepreneurship. It responds to the need to measure the economic, environmental and social performance of Organizations with the aim of strengthening their competitiveness.', 'The Greek Code of Sustainability is a structured reference system regarding the transparency and self-commitment of Organizations in the issues of Sustainable Development and Responsible Entrepreneurship. It responds to the need to measure the economic, environmental and social performance of Organizations with the aim of strengthening their competitiveness.', 'Greece', 'climate', 'in_force', '2020-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_15', ARRAY['sdg8', 'sdg13', 'mandatory', 'sdg16', 'greece', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
