INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06f50cb3-69cd-5e42-9c99-d7fdbcc1fb76', 'Greece Law', 'Law 4548/2018', 'Law 4548/2018 in Greece focuses on reforming the law governing joint-stock companies, emphasizing their commercial nature and defining terms related to financial markets and decision-making processes. The law applies to all joint-stock companies, with specific regulations for those listed on regulated markets or Multilateral Trading Mechanisms. It outlines procedures for establishment, amending statutes, dispute resolution, and decision-making processes within these companies.', 'Law 4548/2018 in Greece focuses on reforming the law governing joint-stock companies, emphasizing their commercial nature and defining terms related to financial markets and decision-making processes. The law applies to all joint-stock companies, with specific regulations for those listed on regulated markets or Multilateral Trading Mechanisms. It outlines procedures for establishment, amending statutes, dispute resolution, and decision-making processes within these companies.', 'Law 4548/2018 in Greece focuses on reforming the law governing joint-stock companies, emphasizing their commercial nature and defining terms related to financial markets and decision-making processes. The law applies to all joint-stock companies, with specific regulations for those listed on regulated markets or Multilateral Trading Mechanisms. It outlines procedures for establishment, amending statutes, dispute resolution, and decision-making processes within these companies.', 'Greece', 'nature', 'in_force', '2018-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_20', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'greece', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
