INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1861c1ab-c78e-5c1f-a67f-9a60bbdfe099', 'Greece Nomos', 'Nomos No. 140384', 'Nomos No. 140384 in Greece focuses on establishing Environmental Quality Standards (EQS) for pollutants and priority substances in water bodies. The policy aims to define a National Quality Monitoring Network and outlines responsibilities for preventing and restoring water damage. It emphasizes compliance with EU directives and involves significant financial investment for implementation.', 'Nomos No. 140384 in Greece focuses on establishing Environmental Quality Standards (EQS) for pollutants and priority substances in water bodies. The policy aims to define a National Quality Monitoring Network and outlines responsibilities for preventing and restoring water damage. It emphasizes compliance with EU directives and involves significant financial investment for implementation.', 'Nomos No. 140384 in Greece focuses on establishing Environmental Quality Standards (EQS) for pollutants and priority substances in water bodies. The policy aims to define a National Quality Monitoring Network and outlines responsibilities for preventing and restoring water damage. It emphasizes compliance with EU directives and involves significant financial investment for implementation.', 'Greece', 'governance', 'in_force', '2017-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_13', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'greece']::text[]) ON CONFLICT (id) DO NOTHING;
