INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('857f0271-873d-5592-8670-ed88f138a9e8', 'Greece Circular', 'Circular no. 62784', 'Circular No.62784/06-06-2017 of the Ministry of the Economy and Development developed according to the provisions of the Directive 2014/95/EU of the European Parliament, requires large companies to disclose specific information regarding the way they operate and manage environmental and social challenges.', 'Circular No.62784/06-06-2017 of the Ministry of the Economy and Development developed according to the provisions of the Directive 2014/95/EU of the European Parliament, requires large companies to disclose specific information regarding the way they operate and manage environmental and social challenges.', 'Circular No.62784/06-06-2017 of the Ministry of the Economy and Development developed according to the provisions of the Directive 2014/95/EU of the European Parliament, requires large companies to disclose specific information regarding the way they operate and manage environmental and social challenges.', 'Greece', 'climate', 'in_force', '2017-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_19', ARRAY['regulations', 'mandatory', 'sdg16', 'greece', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('14340470-8186-5dd4-9496-4fbd0c69cf2e', 'Greece National Strategy for Adaptation to Climate Change', 'National Strategy for Adaptation to Climate Change', 'This strategy aims at addressing risks and opportunities resulting from a changing climate. In particular, it seeks to 10 establish and enhance the short and long-term decision-making procedure regarding adaptation issues, 2) link adaptation with the promotion of a sustainable growth model through the implementation of regional/local action plans, 3) promote adaptation actions and policies in all sectors of the Greek economy, with emphasis on the most vulnerable ones, 4) create a monitoring, evaluation and update mechanism for adaptation actions and policies, and 5) build adaptation capacity and raise public awareness.', 'This strategy aims at addressing risks and opportunities resulting from a changing climate. In particular, it seeks to 10 establish and enhance the short and long-term decision-making procedure regarding adaptation issues, 2) link adaptation with the promotion of a sustainable growth model through the implementation of regional/local action plans, 3) promote adaptation actions and policies in all sectors of the Greek economy, with emphasis on the most vulnerable ones, 4) create a monitoring, evaluation and update mechanism for adaptation actions and policies, and 5) build adaptation capacity and raise public awareness.', 'This strategy aims at addressing risks and opportunities resulting from a changing climate. In particular, it seeks to 10 establish and enhance the short and long-term decision-making procedure regarding adaptation issues, 2) link adaptation with the promotion of a sustainable growth model through the implementation of regional/local action plans, 3) promote adaptation actions and policies in all sectors of the Greek economy, with emphasis on the most vulnerable ones, 4) create a monitoring, evaluation and update mechanism for adaptation actions and policies, and 5) build adaptation capacity and raise public awareness.', 'Greece', 'climate', 'in_force', '2016-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_10', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'sdg10', 'sdg7', 'mandatory', 'greece', 'mandatory_regulations', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8a9f8502-0eab-54b2-b25e-8e13c83d0f5a', 'Greece Law 4308 Greek accounting standards', 'Law 4308 Greek accounting standards', 'Law 4308/2014 introduced differentiated financial reporting requirements for different types of companies depending on their size in terms of annual turnover, number of employees, and total assets, specifying applicable accounting standards.', 'Law 4308/2014 introduced differentiated financial reporting requirements for different types of companies depending on their size in terms of annual turnover, number of employees, and total assets, specifying applicable accounting standards.', 'Law 4308/2014 introduced differentiated financial reporting requirements for different types of companies depending on their size in terms of annual turnover, number of employees, and total assets, specifying applicable accounting standards.', 'Greece', 'climate', 'in_force', '2014-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_11', ARRAY['greece', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f328c3b4-fda5-5d0a-90a5-b092d858de76', 'Greece Hellenic Corporate Governance Code For Listed Companies', 'Hellenic Corporate Governance Code For Listed Companies 2013', 'The code aims at promoting the continuous enhancement of the Greek corporate institutional framework and broader business environment as well as the improvement of the competitiveness of its members and of the Greek economy as a whole.', 'The code aims at promoting the continuous enhancement of the Greek corporate institutional framework and broader business environment as well as the improvement of the competitiveness of its members and of the Greek economy as a whole.', 'The code aims at promoting the continuous enhancement of the Greek corporate institutional framework and broader business environment as well as the improvement of the competitiveness of its members and of the Greek economy as a whole.', 'Greece', 'climate', 'in_force', '2013-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_4', ARRAY['sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'greece', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c01b5d16-d52b-5586-8e01-3a2b04766cc7', 'Greece Nomos YP''', 'Nomos YP'' No. 4072', 'Nomos YP'' No. 4072 is a Greek law focused on improving the business environment by simplifying licensing procedures for various activities. It aims to reduce the number of required permits and streamline the process for issuing licenses. The law emphasizes transparency by posting issued licenses online and promoting electronic submission of applications. It targets strategic investments in industries like industry, energy, and networks, with specific criteria for investment thresholds and job creation. The law is mandatory and signed into effect in 2012.', 'Nomos YP'' No. 4072 is a Greek law focused on improving the business environment by simplifying licensing procedures for various activities. It aims to reduce the number of required permits and streamline the process for issuing licenses. The law emphasizes transparency by posting issued licenses online and promoting electronic submission of applications. It targets strategic investments in industries like industry, energy, and networks, with specific criteria for investment thresholds and job creation. The law is mandatory and signed into effect in 2012.', 'Nomos YP'' No. 4072 is a Greek law focused on improving the business environment by simplifying licensing procedures for various activities. It aims to reduce the number of required permits and streamline the process for issuing licenses. The law emphasizes transparency by posting issued licenses online and promoting electronic submission of applications. It targets strategic investments in industries like industry, energy, and networks, with specific criteria for investment thresholds and job creation. The law is mandatory and signed into effect in 2012.', 'Greece', 'climate', 'in_force', '2012-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_14', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'greece', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('49fcf222-f4f6-5fd7-b4de-c675835040f3', 'Greece Law of the Ministry', 'Law of the Ministry No. 4042', 'According to the 4042/2012 on Waste Management, ''waste'' means any substance or object which the holder discards or intends or is required to discard (art. 11 par. 1). The above quoted definition of “waste” has fully adopted the definition given by the EU Waste Framework Directive 2008/98/EC.', 'According to the 4042/2012 on Waste Management, ''waste'' means any substance or object which the holder discards or intends or is required to discard (art. 11 par. 1). The above quoted definition of “waste” has fully adopted the definition given by the EU Waste Framework Directive 2008/98/EC.', 'According to the 4042/2012 on Waste Management, ''waste'' means any substance or object which the holder discards or intends or is required to discard (art. 11 par. 1). The above quoted definition of “waste” has fully adopted the definition given by the EU Waste Framework Directive 2008/98/EC.', 'Greece', 'climate', 'in_force', '2012-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_16', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'greece', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('52064fce-6446-5764-8e5d-46078b5dba47', 'Greece SEV Corporate Governance Code For Listed Companies', 'SEV Corporate Governance Code For Listed Companies 2011', 'This Corporate Governance Code (hereafter “the Code”) was drafted at the initiative of SEV Hellenic Federation of Enterprises as part of its mandate to promote the continuous enhancement of the Greek corporate institutional framework and broader business environment as well as the improvement of the competitiveness of its members and of the Greek economy as a whole.', 'This Corporate Governance Code (hereafter “the Code”) was drafted at the initiative of SEV Hellenic Federation of Enterprises as part of its mandate to promote the continuous enhancement of the Greek corporate institutional framework and broader business environment as well as the improvement of the competitiveness of its members and of the Greek economy as a whole.', 'This Corporate Governance Code (hereafter “the Code”) was drafted at the initiative of SEV Hellenic Federation of Enterprises as part of its mandate to promote the continuous enhancement of the Greek corporate institutional framework and broader business environment as well as the improvement of the competitiveness of its members and of the Greek economy as a whole.', 'Greece', 'governance', 'in_force', '2011-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_8', ARRAY['mandatory', 'sdg16', 'greece', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
