INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a3362909-ac8f-53dc-9a2d-37c1daad1721', 'Greece packaging and alternative management of packaging', 'Law No. 2939 on packaging and alternative management of packaging', 'This Law No. 2939 on packaging and alternative management of packaging and establishment of the national organisation for alternative management of packaging and other products.', 'This Law No. 2939 on packaging and alternative management of packaging and establishment of the national organisation for alternative management of packaging and other products.', 'This Law No. 2939 on packaging and alternative management of packaging and establishment of the national organisation for alternative management of packaging and other products.', 'Greece', 'circularity', 'in_force', '2001-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_17', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'greece', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f86905fd-0a5d-5d27-8885-73dc065afe53', 'Greece Federation of Greek Industries Principles of Corporate Governance', 'Federation of Greek Industries Principles of Corporate Governance', 'The Federation of Greek Industries Principles of Corporate Governance, established in 2001, outlines principles for publicly-listed companies to organize, operate, and manage in a transparent manner, protecting the interests of stakeholders. It encourages full transparency, active shareholder participation, and long-term balanced development. The principles are voluntary but exceed legal requirements, focusing on improving credibility. Recommendations cover the composition and roles of the Board of Directors, internal regulations, and internal control organization.', 'The Federation of Greek Industries Principles of Corporate Governance, established in 2001, outlines principles for publicly-listed companies to organize, operate, and manage in a transparent manner, protecting the interests of stakeholders. It encourages full transparency, active shareholder participation, and long-term balanced development. The principles are voluntary but exceed legal requirements, focusing on improving credibility. Recommendations cover the composition and roles of the Board of Directors, internal regulations, and internal control organization.', 'The Federation of Greek Industries Principles of Corporate Governance, established in 2001, outlines principles for publicly-listed companies to organize, operate, and manage in a transparent manner, protecting the interests of stakeholders. It encourages full transparency, active shareholder participation, and long-term balanced development. The principles are voluntary but exceed legal requirements, focusing on improving credibility. Recommendations cover the composition and roles of the Board of Directors, internal regulations, and internal control organization.', 'Greece', 'governance', 'in_force', '2001-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_6', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg16', 'greece', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('64fc8c95-e0ec-5ee3-8b6c-531722f5bced', 'Principles on Corporate Governance in Greece: Recommendations', 'Principles on Corporate Governance in Greece: Recommendations for its Competitive Transformation 1999', 'This initiative expresses the wish by the Committee on Corporate Governance in Greece to contribute to the acceleration of the competitive transformation of the framework of corporate governance in Greece, according to the prevailing practices of the member-states of the European Union as well as the recommendations of the OECD, contained in the OECD Principles on Corporate Governance.', 'This initiative expresses the wish by the Committee on Corporate Governance in Greece to contribute to the acceleration of the competitive transformation of the framework of corporate governance in Greece, according to the prevailing practices of the member-states of the European Union as well as the recommendations of the OECD, contained in the OECD Principles on Corporate Governance.', 'This initiative expresses the wish by the Committee on Corporate Governance in Greece to contribute to the acceleration of the competitive transformation of the framework of corporate governance in Greece, according to the prevailing practices of the member-states of the European Union as well as the recommendations of the OECD, contained in the OECD Principles on Corporate Governance.', 'Greece', 'governance', 'in_force', '1999-01-01'::date, 'Greece', 'https://www.carrotsandsticks.org/policies/65_7', ARRAY['guidance_frameworks', 'sdg16', 'greece', 'disclosure', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('360bc656-c03d-5dc3-920f-03875b743ded', 'Guatemala Forest Law Decree', 'Forest Law Decree No. 101-96', 'The importance of the country''s forests as a source of goods and services for a high proportion of the Guatemalan population, as well as the productive potential of the forest lands and natural forests we have in Guatemala, were clearly recognized aspects by the promoters of the current Forestry Law (Decree 101-96 ), when creating a Law with a focus on the promotion of forest production and the protection of the country''s forests, with an institutional framework and policy instruments that allow more than regular, promote forest activity.', 'The importance of the country''s forests as a source of goods and services for a high proportion of the Guatemalan population, as well as the productive potential of the forest lands and natural forests we have in Guatemala, were clearly recognized aspects by the promoters of the current Forestry Law (Decree 101-96 ), when creating a Law with a focus on the promotion of forest production and the protection of the country''s forests, with an institutional framework and policy instruments that allow more than regular, promote forest activity.', 'The importance of the country''s forests as a source of goods and services for a high proportion of the Guatemalan population, as well as the productive potential of the forest lands and natural forests we have in Guatemala, were clearly recognized aspects by the promoters of the current Forestry Law (Decree 101-96 ), when creating a Law with a focus on the promotion of forest production and the protection of the country''s forests, with an institutional framework and policy instruments that allow more than regular, promote forest activity.', 'Guatemala', 'climate', 'in_force', '2013-01-01'::date, 'Guatemala', 'https: