INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8b67e09a-005d-547f-a55b-0336b0bba93d', 'Guatemala Government Agreement Number 431', 'Government Agreement Number 431-2007', 'The Government Agreement Number 431-2007 in Guatemala establishes the Law for Environmental Assessment, Control, and Follow-up to promote sustainable development and protect the environment. It outlines procedures for evaluating, controlling, and monitoring environmental impacts of activities, projects, and industries. The policy aims to ensure harmony between development and environmental protection by determining environmental characteristics and impacts. It applies nationwide through the Ministry of Environment and Natural Resources, emphasizing sustainable practices and compliance with legal obligations.', 'The Government Agreement Number 431-2007 in Guatemala establishes the Law for Environmental Assessment, Control, and Follow-up to promote sustainable development and protect the environment. It outlines procedures for evaluating, controlling, and monitoring environmental impacts of activities, projects, and industries. The policy aims to ensure harmony between development and environmental protection by determining environmental characteristics and impacts. It applies nationwide through the Ministry of Environment and Natural Resources, emphasizing sustainable practices and compliance with legal obligations.', 'The Government Agreement Number 431-2007 in Guatemala establishes the Law for Environmental Assessment, Control, and Follow-up to promote sustainable development and protect the environment. It outlines procedures for evaluating, controlling, and monitoring environmental impacts of activities, projects, and industries. The policy aims to ensure harmony between development and environmental protection by determining environmental characteristics and impacts. It applies nationwide through the Ministry of Environment and Natural Resources, emphasizing sustainable practices and compliance with legal obligations.', 'Guatemala', 'climate', 'in_force', '2007-01-01'::date, 'Guatemala', 'https://www.carrotsandsticks.org/policies/69_3', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'guatemala', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e110a746-e95b-54d9-a30a-1eac52e9efba', 'Guatemala Government Agreement', 'Government Agreement No. 236-2006', 'The Wastewater Discharge and Reuse Regulation entered into force on May 12, 2006 with the purpose of establishing the criteria, permissible limits and requirements that must be met for the discharge and reuse of wastewater, as well as for the disposal of sludge.', 'The Wastewater Discharge and Reuse Regulation entered into force on May 12, 2006 with the purpose of establishing the criteria, permissible limits and requirements that must be met for the discharge and reuse of wastewater, as well as for the disposal of sludge.', 'The Wastewater Discharge and Reuse Regulation entered into force on May 12, 2006 with the purpose of establishing the criteria, permissible limits and requirements that must be met for the discharge and reuse of wastewater, as well as for the disposal of sludge.', 'Guatemala', 'nature', 'in_force', '2006-01-01'::date, 'Guatemala', 'https://www.carrotsandsticks.org/policies/69_4', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg6', 'guatemala', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f3fa12aa-7534-545b-aaf1-19343236a740', 'Guatemala Decree number 93-96 The Law on Electricity', 'Decree number 93-96 The Law on Electricity', 'This Law regulates the development of the set of activities of generation, transportation, distribution and commercialization of electricity.', 'This Law regulates the development of the set of activities of generation, transportation, distribution and commercialization of electricity.', 'This Law regulates the development of the set of activities of generation, transportation, distribution and commercialization of electricity.', 'Guatemala', 'climate', 'in_force', '1996-01-01'::date, 'Guatemala', 'https://www.carrotsandsticks.org/policies/69_6', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'guatemala']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e80224a7-845a-52ce-a00a-cf0caef3b421', 'Guernsey Anti-Greenwashing Guidance and update to the Finance Sector', 'Anti-Greenwashing Guidance and update to the Finance Sector Code of Corporate Governance', 'This policy was published in 2025 by Guernsey. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Guernsey. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Guernsey. It addresses sustainability and corporate responsibility requirements.', 'Guernsey', 'governance', 'in_force', '2025-01-01'::date, 'Guernsey', 'https://www.carrotsandsticks.org/policies/194_2', ARRAY['sdg16', 'guidance_frameworks', 'mandatory', 'guernsey']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('14513191-42dd-516c-b6e0-bef5c375a23f', 'Guernsey Income Tax (Implementation) (OECD Pillar Two GloBE Model', 'The Income Tax (Approved International Agreements) (Implementation) (OECD Pillar Two GloBE Model Rules) Regulations, 2024', 'Guernsey''s 2024 regulations implement the OECD Pillar Two GloBE Model Rules for Income Tax. It outlines rules for Domestic Top-Up Tax (DTT), Multinational Top-Up Tax (MTT), filing obligations, administrative procedures, appeals, penalties, and exceptions. Targeted at entities subject to Guernsey''s income tax laws.', 'Guernsey''s 2024 regulations implement the OECD Pillar Two GloBE Model Rules for Income Tax. It outlines rules for Domestic Top-Up Tax (DTT), Multinational Top-Up Tax (MTT), filing obligations, administrative procedures, appeals, penalties, and exceptions. Targeted at entities subject to Guernsey''s income tax laws.', 'Guernsey''s 2024 regulations implement the OECD Pillar Two GloBE Model Rules for Income Tax. It outlines rules for Domestic Top-Up Tax (DTT), Multinational Top-Up Tax (MTT), filing obligations, administrative procedures, appeals, penalties, and exceptions. Targeted at entities subject to Guernsey''s income tax laws.', 'Guernsey', 'governance', 'in_force', '2024-01-01'::date, 'Guernsey', 'https://www.carrotsandsticks.org/policies/194_3', ARRAY['guernsey', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bbbc0695-d65b-50d7-87df-de7a9b73b9b1', 'Honduras Ministerial Agreement', 'Ministerial Agreement No 016-2015', 'Ministerial Agreement No 016-2015 from Honduras, issued in 2015, focuses on updating the Table of Environmental Categorizations to modernize and issue a new version. It revokes previous agreements and laws related to environmental impact assessment systems. The policy aims to harmonize impact assessment processes in Central America, categorize all productive activities, and enhance environmental authorization procedures. It emphasizes the importance of sustainable practices and compliance with environmental standards.', 'Ministerial Agreement No 016-2015 from Honduras, issued in 2015, focuses on updating the Table of Environmental Categorizations to modernize and issue a new version. It revokes previous agreements and laws related to environmental impact assessment systems. The policy aims to harmonize impact assessment processes in Central America, categorize all productive activities, and enhance environmental authorization procedures. It emphasizes the importance of sustainable practices and compliance with environmental standards.', 'Ministerial Agreement No 016-2015 from Honduras, issued in 2015, focuses on updating the Table of Environmental Categorizations to modernize and issue a new version. It revokes previous agreements and laws related to environmental impact assessment systems. The policy aims to harmonize impact assessment processes in Central America, categorize all productive activities, and enhance environmental authorization procedures. It emphasizes the importance of sustainable practices and compliance with environmental standards.', 'Honduras', 'climate', 'in_force', '2015-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_2', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'honduras']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f6eb7757-60d8-58e3-8dc4-d22fe8bb8c3e', 'Honduras Ministerial Agreement', 'Ministerial Agreement No 1070-2014', 'Establishes the registry of Emissions and Transfer of Pollutants (PRTR), which constitutes an environmental management instrument that contributes to decision-making and the formulation of policies in matters of environmental prevention and control, facilitating public access to information on contaminants that are potentially harmful to the environment.', 'Establishes the registry of Emissions and Transfer of Pollutants (PRTR), which constitutes an environmental management instrument that contributes to decision-making and the formulation of policies in matters of environmental prevention and control, facilitating public access to information on contaminants that are potentially harmful to the environment.', 'Establishes the registry of Emissions and Transfer of Pollutants (PRTR), which constitutes an environmental management instrument that contributes to decision-making and the formulation of policies in matters of environmental prevention and control, facilitating public access to information on contaminants that are potentially harmful to the environment.', 'Honduras', 'climate', 'in_force', '2015-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_5', ARRAY['sdg13', 'other sustainability policy', 'sdg7', 'mandatory', 'honduras', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('773d05a4-8a6b-5728-aa60-abd133f4cd73', 'Honduras Decree', 'Decree No 404-2012', 'This decree establishes the legal framework for the management of the country''s water resources. The decree outlines the roles and responsibilities of different government entities and stakeholders involved in the management of water resources, and establishes procedures for the allocation and use of water. It also establishes a national system for the monitoring and management of water resources, and sets out penalties for violations of water-related regulations.', 'This decree establishes the legal framework for the management of the country''s water resources. The decree outlines the roles and responsibilities of different government entities and stakeholders involved in the management of water resources, and establishes procedures for the allocation and use of water. It also establishes a national system for the monitoring and management of water resources, and sets out penalties for violations of water-related regulations.', 'This decree establishes the legal framework for the management of the country''s water resources. The decree outlines the roles and responsibilities of different government entities and stakeholders involved in the management of water resources, and establishes procedures for the allocation and use of water. It also establishes a national system for the monitoring and management of water resources, and sets out penalties for violations of water-related regulations.', 'Honduras', 'climate', 'in_force', '2014-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_18', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'honduras', 'sdg6']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('265f6a8d-0370-532c-a1f6-2f12cf099bad', 'Honduras Agreement', 'Agreement No 1071-2014', 'In compliance with international conventions, the agreement dictates measures to minimize the risks derived from the use, storage, handling, transportation, treatment and disposal of equipment, oils, waste and soil contaminated with Polychlorinated Biphenyls (PCBs), highly toxic substances, and harmful to human health and the environment.', 'In compliance with international conventions, the agreement dictates measures to minimize the risks derived from the use, storage, handling, transportation, treatment and disposal of equipment, oils, waste and soil contaminated with Polychlorinated Biphenyls (PCBs), highly toxic substances, and harmful to human health and the environment.', 'In compliance with international conventions, the agreement dictates measures to minimize the risks derived from the use, storage, handling, transportation, treatment and disposal of equipment, oils, waste and soil contaminated with Polychlorinated Biphenyls (PCBs), highly toxic substances, and harmful to human health and the environment.', 'Honduras', 'climate', 'in_force', '2014-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_6', ARRAY['other sustainability policy', 'sdg9', 'sdg7', 'sdg11', 'mandatory', 'honduras', 'mandatory_regulations', 'sdg12', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('babe0e63-88ef-579f-8eba-a2c7fd321b93', 'Honduras Decree', 'Decree No 283-2012', 'The purpose of this Law is to regulate mining and metallurgical activities in the country; therefore, it is of public order, general interest and mandatory application.', 'The purpose of this Law is to regulate mining and metallurgical activities in the country; therefore, it is of public order, general interest and mandatory application.', 'The purpose of this Law is to regulate mining and metallurgical activities in the country; therefore, it is of public order, general interest and mandatory application.', 'Honduras', 'climate', 'in_force', '2013-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_17', ARRAY['mandatory', 'other sustainability policy', 'regulations', 'honduras']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cbc4824b-a0b2-58a6-b7b9-6f67750f9824', 'Honduras Decree', 'Decree No 181-2009', 'Establishes the General Water Law of Honduras, which strived to regulate a water policy to define the state’s management priorities.', 'Establishes the General Water Law of Honduras, which strived to regulate a water policy to define the state’s management priorities.', 'Establishes the General Water Law of Honduras, which strived to regulate a water policy to define the state’s management priorities.', 'Honduras', 'governance', 'in_force', '2009-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_15', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'honduras']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9b9ca843-4a86-5091-8637-25273a031438', 'Honduras Decree', 'Decree No 70-2007', 'This law aims at promoting public and private investments in renewable energy production projects. In order to reach that objective, the law seeks to 1) ease investment rules for the sector, 2) ease permitting procedures, 3) create rural jobs, 4) increase efficiency of the country''s electricity supply system, 5) raise wellbeing in rural areas thanks to renewable resources, and 6) look for more alternative sources of energy.', 'This law aims at promoting public and private investments in renewable energy production projects. In order to reach that objective, the law seeks to 1) ease investment rules for the sector, 2) ease permitting procedures, 3) create rural jobs, 4) increase efficiency of the country''s electricity supply system, 5) raise wellbeing in rural areas thanks to renewable resources, and 6) look for more alternative sources of energy.', 'This law aims at promoting public and private investments in renewable energy production projects. In order to reach that objective, the law seeks to 1) ease investment rules for the sector, 2) ease permitting procedures, 3) create rural jobs, 4) increase efficiency of the country''s electricity supply system, 5) raise wellbeing in rural areas thanks to renewable resources, and 6) look for more alternative sources of energy.', 'Honduras', 'climate', 'in_force', '2007-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_19', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'honduras', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('25026b70-8664-5246-befe-62483344d94d', 'Honduras Decree', 'Decree No 189-2004', 'Establishes the law on accounting and auditing standards in line with international standards.', 'Establishes the law on accounting and auditing standards in line with international standards.', 'Establishes the law on accounting and auditing standards in line with international standards.', 'Honduras', 'governance', 'in_force', '2004-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_16', ARRAY['mandatory', 'other sustainability policy', 'regulations', 'honduras']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('87ed9428-bba4-50a9-a596-10eeb929b3f0', 'Honduras Agreement', 'Agreement No 907-2002', 'Agreement No. 907-2002 from Honduras aims to regulate the use of substances depleting the ozone layer by prohibiting their manufacture and deliberate emission. The policy establishes a Progressive Reduction Plan aligned with the Montreal Protocol, requiring registration, reporting, and authorization for importing, exporting, and trading ozone-depleting substances. It mandates supervision of destruction and recycling processes to prevent harmful emissions. The target audience includes companies engaged in the import, export, sale, and use of these substances, with obligations to comply with registration, reporting, and control measures.', 'Agreement No. 907-2002 from Honduras aims to regulate the use of substances depleting the ozone layer by prohibiting their manufacture and deliberate emission. The policy establishes a Progressive Reduction Plan aligned with the Montreal Protocol, requiring registration, reporting, and authorization for importing, exporting, and trading ozone-depleting substances. It mandates supervision of destruction and recycling processes to prevent harmful emissions. The target audience includes companies engaged in the import, export, sale, and use of these substances, with obligations to comply with registration, reporting, and control measures.', 'Agreement No. 907-2002 from Honduras aims to regulate the use of substances depleting the ozone layer by prohibiting their manufacture and deliberate emission. The policy establishes a Progressive Reduction Plan aligned with the Montreal Protocol, requiring registration, reporting, and authorization for importing, exporting, and trading ozone-depleting substances. It mandates supervision of destruction and recycling processes to prevent harmful emissions. The target audience includes companies engaged in the import, export, sale, and use of these substances, with obligations to comply with registration, reporting, and control measures.', 'Honduras', 'climate', 'in_force', '2002-01-01'::date, 'Honduras', 'https://www.carrotsandsticks.org/policies/74_11', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'honduras', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c1142df9-debd-5620-bfac-4d57ebe3aa48', 'Hong Kong Roadmap on Sustainability Disclosure', 'Roadmap on Sustainability Disclosure', 'The Roadmap on Sustainability Disclosure in Hong Kong, published in December 2024, outlines Hong Kong’s strategy to adopt and implement sustainability disclosure standards aligned with the International Sustainability Standards Board (ISSB). This roadmap aims to strengthen the transparency, consistency, and quality of sustainability-related financial disclosures in Hong Kong. Key milestones include:
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00e16235-f0f5-58af-aed1-0019d823c430', 'Hong Kong Discussion Paper: Prototype of a Green Classification', 'Discussion Paper: Prototype of a Green Classification Framework for Hong Kong, 2023', 'This discussion paper outlines the current thinking of the Hong Kong Monetary Authority on local green classification framework (i.e. taxonomy). It seeks to gather feedback from stakeholders on its development and application.', 'This discussion paper outlines the current thinking of the Hong Kong Monetary Authority on local green classification framework (i.e. taxonomy). It seeks to gather feedback from stakeholders on its development and application.', 'This discussion paper outlines the current thinking of the Hong Kong Monetary Authority on local green classification framework (i.e. taxonomy). It seeks to gather feedback from stakeholders on its development and application.', 'Hong Kong', 'climate', 'in_force', '2023-01-01'::date, 'Hong Kong', 'https://www.carrotsandsticks.org/policies/75_66', ARRAY['sdg13', 'hong kong', 'voluntary', 'sdg16', 'sdg12', 'disclosure', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
